-- Seed: current menu (63 dishes) from the printed menu. Run after schema.sql. Re-running updates names and prices.

on conflict (id) do update set name_ru=excluded.name_ru,name_en=excluded.name_en,name_ar=excluded.name_ar,sort=excluded.sort;

on conflict (id) do update set category_id=excluded.category_id,price=excluded.price,image_url=excluded.image_url,name_ru=excluded.name_ru,name_en=excluded.name_en,name_ar=excluded.name_ar,comp_ru=excluded.comp_ru,comp_en=excluded.comp_en,comp_ar=excluded.comp_ar,tags=excluded.tags,sort=excluded.sort;
